SELECT 'gongkao', '观点推断', 'kp-xingce-language-reading-attitude-infer', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "观点推断"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "基于已知推未知，但绝不能过度脑补。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“由此可以推断出作者认为……”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、解题法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "选出的选项必须在材料中有直接或间接的逻辑支撑。带有“必然”、“绝对”、“所有”的绝对化推断选项大概率是错的。"}]}]}$$ AS jsonb), NULL, '观点推断的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "片段阅读", "观点推断"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_reading_attitude_infer", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
